package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                       // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                          // PIC 9(3) len=3 = 0
var WsIncEd string                             // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                             // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                             // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                           // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec TaxRec
var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func fitPic(intDigits int, scale int32, v decimal.Decimal) decimal.Decimal {
	// truncate toward zero to scale
	t := v.Truncate(scale)
	// keep low-order digits: modulo 10^(intDigits+scale) on scaled integer
	s := t.Shift(scale)
	// s should be integer now
	// compute modulus = 10^(intDigits+int(scale))
	modExp := int64(intDigits) + int64(scale)
	mod := decimal.NewFromInt(1)
	for i := int64(0); i < modExp; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	neg := s.IsNegative()
	a := s.Abs()
	// a mod mod
	q := a.Div(mod).Truncate(0)
	r := a.Sub(q.Mul(mod))
	if neg && !r.IsZero() {
		r = r.Neg()
	}
	return r.Shift(-scale)
}

func storeWsTax(v decimal.Decimal) {
	WsTax = fitPic(7, 2, v)
}
func storeWsNet(v decimal.Decimal) {
	WsNet = fitPic(7, 2, v)
}
func storeWsTotalTax(v decimal.Decimal) {
	WsTotalTax = fitPic(9, 2, v)
}
func storeWsCount(v int64) {
	// keep low 3 digits
	m := v % 1000
	if m < 0 {
		m = -m
		// COBOL unsigned; keep simple
	}
	WsCount = m
	// handle negative wrap? counts never negative
	if v < 0 {
		WsCount = ((v % 1000) + 1000) % 1000
	}
}

func formatEdited(v decimal.Decimal, pic string) string {
	// determine dec digits = count of 9/Z after '.'
	dot := strings.Index(pic, ".")
	intDigits := 0
	decDigits := 0
	if dot >= 0 {
		for _, c := range pic[:dot] {
			if c == 'Z' || c == '9' {
				intDigits++
			}
		}
		for _, c := range pic[dot+1:] {
			if c == 'Z' || c == '9' {
				decDigits++
			}
		}
	} else {
		for _, c := range pic {
			if c == 'Z' || c == '9' {
				intDigits++
			}
		}
	}
	// truncate toward zero to decDigits
	t := v.Truncate(int32(decDigits))
	neg := t.IsNegative()
	at := t.Abs()
	scaled := at.Shift(int32(decDigits))
	// scaled is integer
	ipart := scaled.Truncate(0)
	// get int64 safely via string? use Div/Mod with decimal
	pow10dec := decimal.NewFromInt(1)
	for i := 0; i < decDigits; i++ {
		pow10dec = pow10dec.Mul(decimal.NewFromInt(10))
	}
	var intPartDec decimal.Decimal
	var fracDec decimal.Decimal
	if decDigits > 0 {
		intPartDec = ipart.Div(pow10dec).Truncate(0)
		fracDec = ipart.Sub(intPartDec.Mul(pow10dec))
	} else {
		intPartDec = ipart
		fracDec = decimal.NewFromInt(0)
	}
	intStr := intPartDec.String()
	// String may contain ".", strip
	if idx := strings.Index(intStr, "."); idx >= 0 {
		intStr = intStr[:idx]
	}
	if strings.HasPrefix(intStr, "-") || strings.HasPrefix(intStr, "+") {
		intStr = intStr[1:]
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	fracInt := fracDec.IntPart()
	fracStr := ""
	if decDigits > 0 {
		fs := fmt.Sprintf("%d", fracInt)
		if len(fs) < decDigits {
			fs = strings.Repeat("0", decDigits-len(fs)) + fs
		} else if len(fs) > decDigits {
			fs = fs[len(fs)-decDigits:]
		}
		fracStr = fs
	}
	// walk picture
	var out strings.Builder
	intPos := 0
	fracPos := 0
	significant := false
	seenDot := false
	for _, c := range pic {
		switch {
		case c == '.':
			out.WriteRune('.')
			seenDot = true
		case c == ',':
			if significant {
				out.WriteRune(',')
			} else {
				out.WriteRune(' ')
			}
		case c == 'Z' || c == '9':
			if !seenDot {
				d := byte('0')
				if intPos < len(intStr) {
					d = intStr[intPos]
				}
				intPos++
				if c == '9' {
					significant = true
					out.WriteByte(d)
				} else {
					if significant {
						out.WriteByte(d)
					} else {
						if d != '0' {
							significant = true
							out.WriteByte(d)
						} else {
							out.WriteByte(' ')
						}
					}
				}
			} else {
				d := byte('0')
				if fracPos < len(fracStr) {
					d = fracStr[fracPos]
				}
				fracPos++
				out.WriteByte(d)
			}
		default:
			out.WriteRune(c)
		}
	}
	_ = neg
	return out.String()
}

func formatCount(v int64) string {
	m := v % 1000
	if m < 0 {
		m += 1000
	}
	return fmt.Sprintf("%03d", m)
}

func parseIncomeField(s string) decimal.Decimal {
	// s length 8, digits only, spaces => zero
	if len(s) < 8 {
		s = s + strings.Repeat(" ", 8-len(s))
	}
	// replace spaces with 0? If all spaces => 0
	tmp := strings.ReplaceAll(s, " ", "0")
	tmp = strings.TrimSpace(tmp)
	if tmp == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits (should be digits)
	// remove any non-digit? assume digits
	var n int64 = 0
	for i := 0; i < len(tmp); i++ {
		c := tmp[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	return decimal.New(n, -2)
}

func MAINPARA() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty
		inputLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if any (Scanner already strips \n, but \r remains for \r\n? ScanLines strips \r\n)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE TAX-FILE (already closed)
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", formatCount(WsCount), WsTotalEd)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad/truncate to 13
	// careful: line is bytes; assume ASCII, length in chars == bytes
	if len(line) > 13 {
		line = line[:13]
	} else if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	}
	id := line[0:5]
	incField := line[5:13]
	curRec.TrId = id
	curRec.TrIncome = parseIncomeField(incField)
}

func PROCESSPARA() {
	lim1 := decimal.New(1000000, -2) // 10000.00
	lim2 := decimal.New(4000000, -2) // 40000.00
	if curRec.TrIncome.Cmp(lim1) <= 0 {
		// COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
		r := curRec.TrIncome.Mul(decimal.New(10, -2))
		r = r.Round(2)
		storeWsTax(r)
	} else {
		if curRec.TrIncome.Cmp(lim2) <= 0 {
			diff := curRec.TrIncome.Sub(lim1)
			r := diff.Mul(decimal.New(20, -2))
			r = decimal.New(100000, -2).Add(r)
			r = r.Round(2)
			storeWsTax(r)
		} else {
			diff := curRec.TrIncome.Sub(lim2)
			r := diff.Mul(decimal.New(30, -2))
			r = decimal.New(700000, -2).Add(r)
			r = r.Round(2)
			storeWsTax(r)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	nv := curRec.TrIncome.Sub(WsTax).Truncate(2)
	storeWsNet(nv)
	// ADD WS-TAX TO WS-TOTAL-TAX
	storeWsTotalTax(WsTotalTax.Add(WsTax).Truncate(2))
	// ADD 1 TO WS-COUNT
	storeWsCount(WsCount + 1)
	WsIncEd = formatEdited(fitPic(6, 2, curRec.TrIncome), "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", curRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READPARA()
}

func main() {
	MAINPARA()
}
